        "queueText": "12人"
      },
      "asset": {
        "rainCloudIcon": "assets/freeclip-rain-cloud.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "rain_cloud_icon",
      "src": "assets/freeclip-rain-cloud.png",
      "use": "rain cloud icon",
      "description": "雨云图标素材，用于雨天打车卡片左侧天气识别。",
      "bindTo": "/asset/rainCloudIcon"
    }
  ]
}

